import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Archive, BookOpen, Bot, CheckCircle2, ChevronLeft, ChevronRight, CircleAlert,
  Clock3, Download, ExternalLink, FileEdit, FileSearch, History, LibraryBig,
  Plus, RefreshCw, Save, Search, ShieldCheck, Trash2, X,
} from 'lucide-react';
import { blogAdminGet, blogAdminPost, fetchEditorialDraft, generateEditorialDraft } from './api';
import { BlogGscStatus } from './BlogGscStatus';

type BlogSection='overview'|'articles'|'generate'|'review'|'automations';
const SECTIONS:{id:BlogSection;label:string;icon:React.ComponentType<{size?:number}>}[]=[
  {id:'overview',label:'Visão geral',icon:BookOpen},{id:'articles',label:'Artigos e acervo',icon:LibraryBig},{id:'generate',label:'Gerar artigo',icon:Bot},{id:'review',label:'Revisão',icon:ShieldCheck},{id:'automations',label:'Automações',icon:Clock3},
];
const STATUS_LABELS:Record<string,string>={inventario:'Inventário',briefing:'Briefing',rascunho:'Rascunho',revisao_editorial:'Revisão editorial',revisao_clinica:'Revisão clínica',aprovado:'Aprovado — aguardando publicação',publicado:'Publicado',arquivado:'Arquivado'};
const blockTypes=[['p','Parágrafo'],['h2','Título de seção'],['h3','Subtítulo'],['ul','Lista'],['ol','Lista numerada'],['quote','Citação']];

function formatDate(value?:string|null){if(!value)return 'Indisponível';const d=new Date(value);return Number.isNaN(d.getTime())?'Indisponível':new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d);}
function countValue(value:unknown){return typeof value==='number'?String(value):'Indisponível';}
function signature(value:unknown){const text=JSON.stringify(value);let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619);}return (h>>>0).toString(16);}
function persistentOperation(scope:string,payload:unknown,forceNew=false){const key=`karyne_blog_op:${scope}`;const sig=signature(payload);if(!forceNew){try{const old=JSON.parse(localStorage.getItem(key)||'null');if(old?.signature===sig&&old?.operationKey)return old.operationKey;}catch{/* ignore */}}const operationKey=crypto.randomUUID();localStorage.setItem(key,JSON.stringify({signature:sig,operationKey}));return operationKey;}
function updateBlogSection(section:BlogSection){const url=new URL(window.location.href);url.searchParams.set('tab','blog');url.searchParams.set('blogSection',section);history.replaceState({},'',url);}

const StatusPill:React.FC<{status?:string|null}>=({status})=><span className="inline-flex rounded-full bg-[#565E48]/10 border border-[#565E48]/15 px-2 py-1 text-[11px] font-medium text-[#46503B]">{status?STATUS_LABELS[status]||status:'Indisponível'}</span>;
const Notice:React.FC<{type?:'error'|'ok'|'info';children:React.ReactNode}>=({type='info',children})=><div className={`rounded-xl border p-3 text-sm ${type==='error'?'border-[#8B2312]/20 bg-[#8B2312]/8 text-[#8B2312]':type==='ok'?'border-[#365B32]/20 bg-[#365B32]/8 text-[#365B32]':'border-[#D8D1C9] bg-white text-[#2B1B0A]/70'}`}>{children}</div>;

function PreviewArticle({article,presentation}:{article:any;presentation:any}){
  const [html,setHtml]=useState('');const [error,setError]=useState('');const [loading,setLoading]=useState(true);
  const request=JSON.stringify({article,presentation});
  useEffect(()=>{let active=true;setLoading(true);setError('');setHtml('');const timeout=window.setTimeout(()=>{void blogAdminPost({action:'preview',...JSON.parse(request)}).then(result=>{if(!active)return;if(typeof result.html!=='string')throw new Error('Prévia indisponível');setHtml(result.html);}).catch(e=>{if(active)setError(e instanceof Error?e.message:'Prévia indisponível');}).finally(()=>{if(active)setLoading(false);});},250);return()=>{active=false;window.clearTimeout(timeout);};},[request]);
  return <section className="bg-white border border-[#E4DFD9] rounded-2xl overflow-hidden"><div className="px-4 py-2 text-[11px] text-[#565E48]">Prévia privada · não publicada</div>{loading?<Notice>Preparando prévia…</Notice>:error?<Notice type="error">{error}</Notice>:<iframe title="Prévia privada do artigo" sandbox="" srcDoc={html} className="w-full min-h-[680px] border-0"/>}</section>;
}

function useModalAccessibility(onClose:()=>void){
  const close=useRef(onClose);close.current=onClose;
  useEffect(()=>{const trigger=document.activeElement as HTMLElement|null;const modal=document.querySelector<HTMLElement>('[role="dialog"]');modal?.focus();const key=(event:KeyboardEvent)=>{if(event.key==='Escape'){event.preventDefault();close.current();}if(event.key==='Tab'&&modal){const elements=Array.from(modal.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]'));const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===modal)){event.preventDefault();first?.focus();}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);trigger?.focus();};},[]);
}

function BlockEditor({body,onChange}:{body:any[];onChange:(body:any[])=>void}){
  const patch=(index:number,patch:any)=>onChange(body.map((b,i)=>i===index?{...b,...patch}:b));
  return <div className="space-y-3">{body.map((block,index)=><div key={index} className="rounded-xl border border-[#E4DFD9] bg-[#FAF8F4] p-3"><div className="flex gap-2 items-center"><select value={block.type} onChange={e=>{const type=e.target.value;patch(index,type==='ul'||type==='ol'?{type,items:block.items||[block.text||''],text:undefined}:{type,text:block.text||(block.items||[]).join(' '),items:undefined});}} className="rounded-lg border border-[#D8D1C9] bg-white px-2 py-2 text-sm">{blockTypes.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select><button onClick={()=>onChange(body.filter((_,i)=>i!==index))} className="ml-auto p-2 text-[#8B2312]" title="Remover bloco"><Trash2 size={15}/></button></div>{block.type==='ul'||block.type==='ol'?<textarea value={(block.items||[]).join('\n')} onChange={e=>patch(index,{items:e.target.value.split('\n')})} rows={4} className="mt-2 w-full rounded-lg border border-[#D8D1C9] p-2 text-sm" placeholder="Um item por linha"/>:<textarea value={block.text||''} onChange={e=>patch(index,{text:e.target.value})} rows={block.type==='p'?4:2} className="mt-2 w-full rounded-lg border border-[#D8D1C9] p-2 text-sm"/>}</div>)}<button onClick={()=>onChange([...body,{type:'p',text:''}])} className="inline-flex items-center gap-1 text-sm px-3 py-2 rounded-xl border border-[#D8D1C9] bg-white"><Plus size={14}/>Adicionar bloco</button></div>;
}

function ArticleDetail({articleId,onClose,onSaved}:{articleId:string;onClose:()=>void;onSaved?:()=>void}){
  useModalAccessibility(onClose);
  const [data,setData]=useState<any>(null);const [mode,setMode]=useState<'preview'|'edit'|'history'|'sources'>('preview');const [form,setForm]=useState<any>(null);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [sourceDetail,setSourceDetail]=useState<any>(null);
  const load=async()=>{setLoading(true);setError('');try{const json=await blogAdminGet({view:'article',id:articleId});setData(json);const latest=json.detail.versions?.[0];const payload=latest?.content_payload_json||{};setForm({title:payload.title||latest?.title||json.detail.article.working_title,description:payload.description||latest?.description||'',slug:json.detail.article.target_slug,body:payload.body||latest?.body_json||[],ctaLabel:payload.ctaLabel||'Conhecer a avaliação inicial',internalLinks:payload.internalLinks||[],references:payload.references||latest?.references_json||[],presentation:latest?.presentation_payload_json||{kind:'none',subject:'sem-imagem-adequada',reason:'Selecione uma apresentação antes de salvar',image:null},changeNote:''});}catch(e){setError(e instanceof Error?e.message:'Falha ao abrir artigo');}finally{setLoading(false);}};
  useEffect(()=>{void load();},[articleId]);
  if(loading)return <Notice>Carregando artigo…</Notice>;if(error&&!data)return <Notice type="error">{error}</Notice>;
  const detail=data?.detail;const latest=detail?.versions?.[0];const published=detail?.publications?.find((p:any)=>p.publication_status==='published');const publicVersion=published?detail.versions.find((v:any)=>v.id===published.article_version_id):null;
  const save=async()=>{setBusy(true);setError('');setNotice('');try{const payload={action:'save-version',articleId,expectedVersionId:latest.id,expectedVersionNumber:latest.version_number,article:form,changeNote:form.changeNote};const operationKey=persistentOperation(`save:${articleId}:${latest.id}`,payload);await blogAdminPost({...payload,operationKey});setNotice('Nova versão salva. Aprovações anteriores não foram herdadas e a versão publicada permaneceu intacta.');await load();onSaved?.();}catch(e){setError(e instanceof Error?e.message:'Falha ao salvar');}finally{setBusy(false);}};
  const exportSnapshot=async()=>{setBusy(true);setError('');try{const json=await blogAdminPost({action:'export-snapshot',articleId,versionId:latest.id});const blob=new Blob([JSON.stringify(json.snapshot,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`blog-${json.snapshot.article.slug}-v${json.snapshot.article.version}.json`;a.click();URL.revokeObjectURL(url);setNotice('Snapshot privado exportado. Isso não publica nem altera o artigo em produção.');}catch(e){setError(e instanceof Error?e.message:'Falha ao exportar');}finally{setBusy(false);}};
  const setPresentation=(value:string)=>{if(value==='none')setForm((f:any)=>({...f,presentation:{kind:'none',reviewStatus:'reviewed',subject:'sem-imagem-adequada',reason:f.presentation?.reason||'',image:null}}));else{const asset=data.assets.find((a:any)=>a.file===value);setForm((f:any)=>({...f,presentation:{kind:'image',reviewStatus:'reviewed',subject:asset.label,image:{file:asset.file,label:asset.label,alt:asset.defaultAlt,caption:asset.defaultCaption||''}}}));}};
  const openSource=async(id:string)=>{setError('');try{const json=await blogAdminGet({view:'source',id});setSourceDetail(json.source);}catch(e){setError(e instanceof Error?e.message:'Falha ao abrir fonte');}};
  return <div role="dialog" aria-modal="true" aria-label="Artigo privado" tabIndex={-1} className="fixed inset-0 z-50 bg-black/35 p-3 md:p-6 overflow-y-auto"><div className="max-w-6xl mx-auto bg-[#F6F0E9] min-h-[90vh] rounded-2xl shadow-xl border border-[#D8D1C9] overflow-hidden"><div className="sticky top-0 z-10 bg-[#F6F0E9]/95 backdrop-blur border-b border-[#D8D1C9] p-4 flex items-center gap-3"><div><div className="font-serif text-xl text-[#222D19]">{detail.article.working_title}</div><div className="text-[12px] text-[#2B1B0A]/50">Trabalho v{latest?.version_number??'—'} · público v{publicVersion?.version_number??'nenhum'} · {STATUS_LABELS[detail.article.status]||detail.article.status}</div></div><button aria-label="Fechar artigo" onClick={onClose} className="ml-auto p-2 rounded-xl border border-[#D8D1C9] bg-white"><X size={17}/></button></div>
    <div className="p-4 md:p-6"><div className="flex flex-wrap gap-2 mb-5">{(['preview','edit','history','sources'] as const).map(item=><button key={item} onClick={()=>setMode(item)} className={`px-3 py-2 rounded-xl text-sm ${mode===item?'bg-[#222D19] text-white':'bg-white border border-[#D8D1C9]'}`}>{item==='preview'?'Prévia':item==='edit'?'Editar':item==='history'?'Versões e revisões':'Fontes'}</button>)}{published?.canonical_url&&<a href={published.canonical_url} target="_blank" rel="noreferrer" className="ml-auto inline-flex items-center gap-1 px-3 py-2 rounded-xl border border-[#D8D1C9] bg-white text-sm">Ver versão pública <ExternalLink size={14}/></a>}</div>
    {error&&<div className="mb-4"><Notice type="error">{error}</Notice></div>}{notice&&<div className="mb-4"><Notice type="ok">{notice}</Notice></div>}
    {mode==='preview'&&<PreviewArticle article={form} presentation={form.presentation}/>}
    {mode==='edit'&&<div className="grid grid-cols-1 lg:grid-cols-[1fr_320px] gap-5"><div className="space-y-5"><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><label className="text-[11px] uppercase text-[#2B1B0A]/45">Título</label><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} className="mt-1 w-full border border-[#D8D1C9] rounded-xl px-3 py-2.5"/><label className="block mt-4 text-[11px] uppercase text-[#2B1B0A]/45">Descrição</label><textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} rows={3} className="mt-1 w-full border border-[#D8D1C9] rounded-xl px-3 py-2.5"/><div className="mt-4 text-[11px] text-[#2B1B0A]/45">Slug estável: <code>{form.slug}</code></div></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium text-sm mb-3">Conteúdo</div><BlockEditor body={form.body} onChange={body=>setForm({...form,body})}/></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium text-sm mb-3">Referências</div>{form.references.map((ref:any,i:number)=><div key={i} className="grid grid-cols-1 md:grid-cols-[1fr_1fr_auto] gap-2 mb-2"><input value={ref.title||''} onChange={e=>setForm({...form,references:form.references.map((r:any,j:number)=>j===i?{...r,title:e.target.value}:r)})} placeholder="Título" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input value={ref.url||''} onChange={e=>setForm({...form,references:form.references.map((r:any,j:number)=>j===i?{...r,url:e.target.value}:r)})} placeholder="https://…" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input aria-label="O que a referência sustenta" value={ref.supports||''} onChange={e=>setForm({...form,references:form.references.map((r:any,j:number)=>j===i?{...r,supports:e.target.value}:r)})} placeholder="O que esta referência sustenta" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input aria-label="Data da verificação da referência" type="date" value={ref.verifiedAt||''} onChange={e=>setForm({...form,references:form.references.map((r:any,j:number)=>j===i?{...r,verifiedAt:e.target.value}:r)})} className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><button onClick={()=>setForm({...form,references:form.references.filter((_:any,j:number)=>j!==i)})} className="p-2 text-[#8B2312]"><Trash2 size={15}/></button></div>)}<button onClick={()=>setForm({...form,references:[...form.references,{title:'',url:'',supports:'',verifiedAt:''}]})} className="text-sm border border-[#D8D1C9] rounded-xl px-3 py-2"><Plus size={14} className="inline mr-1"/>Referência</button></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium text-sm mb-1">Links internos</div><p className="text-[12px] text-[#2B1B0A]/45 mb-3">Somente rotas internas permitidas, como <code>/</code> ou <code>/blog/slug/</code>.</p>{form.internalLinks.map((link:any,i:number)=>{const destination=link.slug?`/blog/${link.slug}/`:(link.url||'');return <div key={i} className="grid grid-cols-1 md:grid-cols-[1fr_1fr_auto] gap-2 mb-2"><input value={link.label||''} onChange={e=>setForm({...form,internalLinks:form.internalLinks.map((r:any,j:number)=>j===i?{...r,label:e.target.value}:r)})} placeholder="Texto do link" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input value={destination} onChange={e=>setForm({...form,internalLinks:form.internalLinks.map((r:any,j:number)=>j===i?{label:r.label||'',url:e.target.value}:r)})} placeholder="/blog/outro-artigo/" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><button onClick={()=>setForm({...form,internalLinks:form.internalLinks.filter((_:any,j:number)=>j!==i)})} className="p-2 text-[#8B2312]"><Trash2 size={15}/></button></div>;})}<button onClick={()=>setForm({...form,internalLinks:[...form.internalLinks,{label:'',url:'/'}]})} className="text-sm border border-[#D8D1C9] rounded-xl px-3 py-2"><Plus size={14} className="inline mr-1"/>Link interno</button></section></div>
      <aside className="space-y-4"><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium text-sm">Apresentação</div><select value={form.presentation?.kind==='image'?form.presentation.image?.file:'none'} onChange={e=>setPresentation(e.target.value)} className="mt-2 w-full rounded-xl border border-[#D8D1C9] px-2 py-2 text-sm"><option value="none">Sem imagem adequada</option>{data.assets.map((asset:any)=><option key={asset.file} value={asset.file}>{asset.label}</option>)}</select>{form.presentation?.kind==='image'?<><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Alt</label><input value={form.presentation.image.alt||''} onChange={e=>setForm({...form,presentation:{...form.presentation,image:{...form.presentation.image,alt:e.target.value}}})} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Legenda</label><textarea value={form.presentation.image.caption||''} onChange={e=>setForm({...form,presentation:{...form.presentation,image:{...form.presentation.image,caption:e.target.value}}})} rows={3} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/></>:<><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Motivo</label><textarea value={form.presentation.reason||''} onChange={e=>setForm({...form,presentation:{...form.presentation,reason:e.target.value}})} rows={3} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/></>}</section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><label className="text-[11px] uppercase text-[#2B1B0A]/45">Nota da alteração</label><textarea value={form.changeNote} onChange={e=>setForm({...form,changeNote:e.target.value})} rows={3} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><button disabled={busy} onClick={()=>void save()} className="mt-3 w-full inline-flex justify-center items-center gap-2 bg-[#222D19] text-white rounded-xl px-3 py-2.5 text-sm font-medium disabled:opacity-50"><Save size={15}/>Salvar como nova versão</button><p className="mt-2 text-[11px] text-[#2B1B0A]/45">Salvar não publica. Qualquer alteração cria nova versão e exige novas aprovações para os hashes atuais.</p></section><button disabled={busy||!detail.approvals?.editorial||!detail.approvals?.clinical} onClick={()=>void exportSnapshot()} className="w-full inline-flex justify-center items-center gap-2 bg-white border border-[#D8D1C9] rounded-xl px-3 py-2.5 text-sm disabled:opacity-50"><Download size={15}/>Baixar pacote aprovado</button></aside></div>}
    {mode==='history'&&<div className="grid grid-cols-1 lg:grid-cols-2 gap-4"><section className="bg-white border border-[#E4DFD9] rounded-2xl overflow-hidden"><div className="p-3 font-medium text-sm border-b border-[#E4DFD9]">Histórico de versões</div>{detail.versions.map((v:any)=><div key={v.id} className="p-3 border-b border-[#E4DFD9] last:border-0"><div className="flex justify-between"><span className="font-medium">v{v.version_number} · {v.title}</span><span className="text-[11px] text-[#2B1B0A]/45">{formatDate(v.created_at)}</span></div><details className="mt-1 text-[11px] text-[#2B1B0A]/45"><summary>Detalhes da versão</summary><div>Conteúdo: {v.content_sha256||'Indisponível'}</div><div>Apresentação: {v.presentation_sha256||'Indisponível'}</div></details><div className="text-[12px] mt-1">{v.change_note||'Sem nota de alteração.'}</div></div>)}</section><section className="bg-white border border-[#E4DFD9] rounded-2xl overflow-hidden"><div className="p-3 font-medium text-sm border-b border-[#E4DFD9]">Revisões registradas</div>{detail.reviews.map((r:any)=><div key={r.id} className="p-3 border-b border-[#E4DFD9] last:border-0"><div className="flex justify-between"><span className="font-medium">{r.review_type==='clinical'?'Clínica':'Editorial'} · {r.status==='approved'?'Aprovada':'Correções solicitadas'}</span><span className="text-[11px] text-[#2B1B0A]/45">{formatDate(r.reviewed_at)}</span></div><details className="text-[12px] mt-1"><summary>Identidade e versão registradas</summary><div>Versão: {detail.versions.find((v:any)=>v.id===r.article_version_id)?.version_number??'Indisponível'}</div><div>Responsável informado: {r.reviewer_name||'não informado'}</div><div>Operador que registrou: {r.recorded_by_user_id||'Indisponível'}</div></details><div className="text-[12px] text-[#2B1B0A]/60 mt-1">{r.notes||'Sem observação.'}</div></div>)}{!detail.reviews.length&&<div className="p-5 text-sm text-[#2B1B0A]/45">Nenhuma revisão registrada.</div>}</section></div>}
    {mode==='sources'&&<div className="space-y-3">{detail.sources.map((source:any)=><section key={source.id} className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="flex gap-3"><div><div className="font-medium">{source.source_title||source.source_slug||source.external_id}</div><div className="text-[12px] text-[#2B1B0A]/45 mt-1">ID legado {source.external_id} · {source.has_text?'texto disponível':'sem texto disponível'}</div></div><button onClick={()=>void openSource(source.id)} className="ml-auto text-sm border border-[#D8D1C9] rounded-xl px-3 py-2">Ler fonte</button></div><p className="text-sm text-[#2B1B0A]/65 mt-3 whitespace-pre-line">{source.body_excerpt}</p></section>)}{sourceDetail&&<section className="bg-white border border-[#565E48]/30 rounded-2xl p-4"><div className="flex"><div className="font-serif text-xl">{sourceDetail.source_title}</div><button onClick={()=>setSourceDetail(null)} className="ml-auto"><X size={16}/></button></div><div className="text-[12px] text-[#2B1B0A]/45 mt-1">Publicada: {formatDate(sourceDetail.published_at_source)} · atualizada: {formatDate(sourceDetail.modified_at_source)}</div><div className="mt-4 max-h-[50vh] overflow-y-auto whitespace-pre-line text-sm leading-6 text-[#2B1B0A]/80">{sourceDetail.normalized_body_text||'Fonte sem texto disponível.'}</div></section>}</div>}
    </div></div></div>;
}

function OverviewSection({go}:{go:(s:BlogSection)=>void}){
  const [data,setData]=useState<any>(null);const [error,setError]=useState('');const [loading,setLoading]=useState(true);const load=async()=>{setLoading(true);setError('');try{setData((await blogAdminGet({view:'overview'})).overview);}catch(e){setError(e instanceof Error?e.message:'Visão geral indisponível');}finally{setLoading(false);}};useEffect(()=>{void load();},[]);
  const cards=[['articles','Artigos no acervo',data?.counts?.articles,'articles'],['published','Publicados',data?.counts?.published,'articles'],['review','Aguardando revisão',data?.counts?.review_pending,'review'],['approved','Aprovados, aguardando publicação',data?.counts?.approved_waiting_publication,'review'],['indexed','URLs indexadas conhecidas',data?.counts?.indexed,'automations']] as const;
  return <div className="space-y-4"><div className="flex justify-between items-start"><div><h2 className="font-serif text-2xl text-[#222D19]">Operação editorial</h2><p className="text-sm text-[#2B1B0A]/55 mt-1">Conteúdo, revisão e indexação em uma visão. Dados de ausência continuam marcados como indisponíveis, não como zero.</p></div><button onClick={()=>void load()} className="p-2 rounded-xl border border-[#D8D1C9] bg-white"><RefreshCw size={15} className={loading?'animate-spin':''}/></button></div>{error&&<Notice type="error">{error}</Notice>}<div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-5 gap-3">{cards.map(([key,labelText,value,target])=><button key={key} onClick={()=>go(target as BlogSection)} className="text-left bg-white border border-[#E4DFD9] rounded-2xl p-4 hover:border-[#565E48]/40"><div className="text-[11px] uppercase tracking-wide text-[#2B1B0A]/45">{labelText}</div><div className="font-serif text-3xl mt-2 text-[#222D19]">{countValue(value)}</div></button>)}</div><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="text-[11px] uppercase text-[#2B1B0A]/45">Última execução GSC observada</div>{data?.last_run?<div className="mt-2 flex flex-wrap gap-x-6 gap-y-2 text-sm"><span>{formatDate(data.last_run.updated_at)}</span><span>{data.last_run.trigger_source==='manual'?'Manual':data.last_run.trigger_source==='scheduled'?'Agendada':'Origem não registrada'}</span><span>Status: {data.last_run.status}</span></div>:<div className="mt-2 text-sm text-[#2B1B0A]/45">Indisponível</div>}<div className="mt-3 text-[11px] text-[#2B1B0A]/40">Leitura da central: {formatDate(data?.data_updated_at)}</div></section></div>;
}

function ArticlesSection(){
  const [mode,setMode]=useState<'articles'|'sources'>('articles');const [q,setQ]=useState('');const [status,setStatus]=useState('');const [page,setPage]=useState(1);const [data,setData]=useState<any>(null);const [error,setError]=useState('');const [selected,setSelected]=useState<string|null>(null);const [source,setSource]=useState<any>(null);const load=async(target=page)=>{setError('');try{const json=await blogAdminGet({view:mode,q,status:mode==='articles'?status:undefined,page:target,pageSize:20});setData(json);setPage(target);}catch(e){setError(e instanceof Error?e.message:'Falha ao carregar acervo');}};useEffect(()=>{void load(1);},[mode,status]);
  const total=data?.total;const hasNext=typeof total==='number'?page*20<total:(data?.items?.length||0)===20;const search=()=>void load(1);
  const openSource=async(id:string)=>{try{setSource((await blogAdminGet({view:'source',id})).source);}catch(e){setError(e instanceof Error?e.message:'Falha ao abrir fonte');}};
  return <div className="space-y-4"><div className="flex flex-wrap gap-2"><button onClick={()=>setMode('articles')} className={`px-3 py-2 rounded-xl text-sm ${mode==='articles'?'bg-[#222D19] text-white':'bg-white border border-[#D8D1C9]'}`}>Artigos</button><button onClick={()=>setMode('sources')} className={`px-3 py-2 rounded-xl text-sm ${mode==='sources'?'bg-[#222D19] text-white':'bg-white border border-[#D8D1C9]'}`}>Acervo legado</button></div><div className="bg-white border border-[#E4DFD9] rounded-2xl p-3 flex flex-col md:flex-row gap-2"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-3 text-[#2B1B0A]/40"/><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&search()} placeholder={mode==='articles'?'Buscar título ou tema':'Buscar título, slug ou ID legado'} className="w-full pl-9 pr-3 py-2.5 rounded-xl border border-[#D8D1C9]"/></div>{mode==='articles'&&<select value={status} onChange={e=>setStatus(e.target.value)} className="rounded-xl border border-[#D8D1C9] px-3 py-2.5 text-sm"><option value="">Todos os status</option>{Object.entries(STATUS_LABELS).map(([value,labelText])=><option key={value} value={value}>{labelText}</option>)}</select>}<button onClick={search} className="rounded-xl bg-[#222D19] text-white px-4 py-2.5 text-sm">Buscar</button></div>{error&&<Notice type="error">{error}</Notice>}
    {mode==='articles'?<div className="bg-white border border-[#E4DFD9] rounded-2xl overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-sm"><thead><tr className="bg-[#F6F0E9] text-left text-[11px] uppercase text-[#2B1B0A]/45"><th className="px-4 py-3">Artigo</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Trabalho</th><th className="px-4 py-3">Público</th><th className="px-4 py-3">Aprovações atuais</th><th className="px-4 py-3">GSC</th></tr></thead><tbody className="divide-y divide-[#E4DFD9]">{(data?.items||[]).map((item:any)=><tr key={item.id} onClick={()=>setSelected(item.id)} className="cursor-pointer hover:bg-[#F6F0E9]/60"><td className="px-4 py-3"><div className="font-medium text-[#222D19]">{item.working_title}</div><div className="text-[11px] text-[#2B1B0A]/40">/{item.target_slug}</div></td><td className="px-4 py-3"><StatusPill status={item.status}/></td><td className="px-4 py-3">v{item.work_version??'—'}</td><td className="px-4 py-3">{item.public_version?`v${item.public_version}`:'não publicado'}</td><td className="px-4 py-3 text-[12px]">Editorial {item.approvals?.editorial?'✓':'—'} · Clínica {item.approvals?.clinical?'✓':'—'}</td><td className="px-4 py-3 text-[12px]">{item.gsc?.knowledge_state||'Indisponível'}</td></tr>)}{!(data?.items||[]).length&&<tr><td colSpan={6} className="px-4 py-8 text-center text-[#2B1B0A]/45">Nenhum artigo encontrado.</td></tr>}</tbody></table></div></div>:<div className="grid grid-cols-1 md:grid-cols-2 gap-3">{(data?.items||[]).map((item:any)=><button key={item.id} onClick={()=>void openSource(item.id)} className="text-left bg-white border border-[#E4DFD9] rounded-2xl p-4 hover:border-[#565E48]/40"><div className="flex gap-3"><Archive size={18} className="text-[#565E48] mt-0.5"/><div><div className="font-medium">{item.source_title||item.source_slug||item.external_id}</div><div className="text-[11px] text-[#2B1B0A]/45 mt-1">ID {item.external_id} · {item.has_text?'texto disponível':'sem texto: geração bloqueada'}</div></div></div><p className="mt-3 text-sm text-[#2B1B0A]/60 line-clamp-3">{item.normalized_excerpt||item.body_excerpt||'Sem resumo.'}</p></button>)}</div>}
    <div className="flex justify-between"><button disabled={page<=1} onClick={()=>void load(page-1)} className="px-3 py-2 rounded-xl border border-[#D8D1C9] bg-white disabled:opacity-40"><ChevronLeft size={15} className="inline"/> Anterior</button><span className="text-sm text-[#2B1B0A]/45 self-center">Página {page}{typeof total==='number'?` · ${total} itens`:''}</span><button disabled={!hasNext} onClick={()=>void load(page+1)} className="px-3 py-2 rounded-xl border border-[#D8D1C9] bg-white disabled:opacity-40">Próxima <ChevronRight size={15} className="inline"/></button></div>
    {selected&&<ArticleDetail articleId={selected} onClose={()=>setSelected(null)} onSaved={()=>void load(page)}/>} {source&&<div role="dialog" aria-modal="true" aria-label="Artigo privado" tabIndex={-1} className="fixed inset-0 z-50 bg-black/35 p-4 overflow-y-auto"><div className="max-w-4xl mx-auto bg-[#F6F0E9] rounded-2xl p-5 border border-[#D8D1C9]"><div className="flex"><div><div className="font-serif text-2xl">{source.source_title}</div><div className="text-[12px] text-[#2B1B0A]/45">ID legado {source.external_id} · {formatDate(source.published_at_source)}</div></div><button onClick={()=>setSource(null)} className="ml-auto p-2"><X size={17}/></button></div><div className="mt-5 bg-white border border-[#E4DFD9] rounded-xl p-4 whitespace-pre-line text-sm leading-6 max-h-[70vh] overflow-y-auto">{source.normalized_body_text||'Fonte sem texto disponível.'}</div></div></div>}
  </div>;
}

function GenerateSection(){
  const [sourceQuery,setSourceQuery]=useState('');const [sources,setSources]=useState<any[]>([]);const [selected,setSelected]=useState<any>(null);const [objective,setObjective]=useState('Criar um artigo útil e clinicamente prudente a partir da fonte legado e das referências verificadas.');const [intent,setIntent]=useState('Informacional');const [contribution,setContribution]=useState('Atualizar e organizar o conteúdo legado com foco em clareza e próximos passos seguros.');const [links,setLinks]=useState<string[]>(['/']);const [refs,setRefs]=useState<any[]>([{title:'',url:'',supports:'',verifiedAt:''}]);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [draft,setDraft]=useState<any>(null);const [presentation,setPresentation]=useState<any>({kind:'none',reviewStatus:'reviewed',subject:'sem-imagem-adequada',reason:'Sem imagem adequada selecionada para esta pauta.',image:null});const [assets,setAssets]=useState<any[]>([]);
  const searchSources=async()=>{setError('');try{const json=await blogAdminGet({view:'sources',q:sourceQuery,page:1,pageSize:12});setSources(json.items||[]);}catch(e){setError(e instanceof Error?e.message:'Falha ao buscar fontes');}};useEffect(()=>{void searchSources();void blogAdminGet({view:'assets'}).then(j=>setAssets(j.assets||[])).catch(()=>{});const saved=localStorage.getItem('karyne_blog_generation:last');if(saved){try{const state=JSON.parse(saved);if(state?.operationKey)void fetchEditorialDraft(state.operationKey).then(result=>{if(result?.draft)setDraft(result.draft);}).catch(()=>{});}catch{/*ignore*/}}},[]);
  const requestShape=useMemo(()=>selected?{sourceId:String(selected.external_id),briefing:{objective,searchIntent:intent,editorialContribution:contribution,allowedInternalLinks:links.filter(Boolean)},references:refs}:null,[selected,objective,intent,contribution,links,refs]);
  const generate=async(forceNew=false)=>{if(!selected||!requestShape)return;setBusy(true);setError('');setNotice('');try{const operationKey=persistentOperation(`generate:${selected.external_id}`,requestShape,forceNew);localStorage.setItem('karyne_blog_generation:last',JSON.stringify({operationKey,sourceId:selected.external_id}));const result=await generateEditorialDraft({...requestShape,operationKey});const resolved=result.draft||result;if(resolved)setDraft(resolved);if(result.pending)setNotice('A operação ficou em estado pendente/incerto. O painel preservou o identificador e não repetirá a chamada automaticamente.');else setNotice(result.reused?'Rascunho existente recuperado sem nova chamada paga.':'Rascunho gerado e salvo como privado. Ainda exige revisão humana.');}catch(e){setError(e instanceof Error?e.message:'Geração não concluída');}finally{setBusy(false);}};
  const draftRow=draft?.payload_json?draft:null;const payload=draft?.payload_json||draft?.draft||draft;const status=draftRow?.status||draft?.status||payload?.status;
  const reconcile=async()=>{const operationKey=JSON.parse(localStorage.getItem('karyne_blog_generation:last')||'{}').operationKey;if(!operationKey)return;setBusy(true);try{const result=await fetchEditorialDraft(operationKey);if(result?.draft)setDraft(result.draft);}catch(e){setError(e instanceof Error?e.message:'Falha ao reconciliar');}finally{setBusy(false);}};
  const choosePresentation=(value:string)=>{if(value==='none')setPresentation({kind:'none',reviewStatus:'reviewed',subject:'sem-imagem-adequada',reason:'Sem imagem adequada selecionada para esta pauta.',image:null});else{const asset=assets.find(a=>a.file===value);setPresentation({kind:'image',reviewStatus:'reviewed',subject:asset.label,image:{file:asset.file,label:asset.label,alt:asset.defaultAlt,caption:asset.defaultCaption||''}});}};
  const promote=async()=>{const operationKey=JSON.parse(localStorage.getItem('karyne_blog_generation:last')||'{}').operationKey;if(!operationKey)return;setBusy(true);setError('');try{const op=persistentOperation(`promote:${operationKey}`,{operationKey,presentation});const result=await blogAdminPost({action:'promote-draft',draftOperationKey:operationKey,operationKey:op,presentation});setNotice(`Versão editável criada (v${result.result.versionNumber}). Ela permanece privada e vai para revisão editorial.`);}catch(e){setError(e instanceof Error?e.message:'Falha ao criar versão editável');}finally{setBusy(false);}};
  return <div className="grid grid-cols-1 xl:grid-cols-[380px_1fr] gap-4"><aside className="space-y-4"><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">1. Fonte legado</div><div className="mt-3 flex gap-2"><input value={sourceQuery} onChange={e=>setSourceQuery(e.target.value)} className="flex-1 rounded-xl border border-[#D8D1C9] px-3 py-2" placeholder="Buscar fonte"/><button onClick={()=>void searchSources()} className="p-2 border border-[#D8D1C9] rounded-xl"><Search size={15}/></button></div><div className="mt-3 max-h-72 overflow-y-auto space-y-2">{sources.map(item=><button key={item.id} disabled={!item.has_text} onClick={()=>setSelected(item)} className={`w-full text-left rounded-xl border p-3 ${selected?.id===item.id?'border-[#565E48] bg-[#565E48]/8':'border-[#E4DFD9]'} disabled:opacity-45`}><div className="text-sm font-medium">{item.source_title||item.external_id}</div><div className="text-[11px] text-[#2B1B0A]/45">ID {item.external_id} · {item.has_text?'pronta para geração':'sem texto: bloqueada'}</div></button>)}</div></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">Uso de IA</div><p className="text-[12px] text-[#2B1B0A]/55 mt-2">A geração usa provedores configurados no servidor e pode consumir cota/custo. O clique é explícito, idempotente e uma operação incerta não é repetida automaticamente.</p><button disabled={busy||!selected?.has_text} onClick={()=>void generate(false)} className="mt-3 w-full bg-[#222D19] text-white rounded-xl px-3 py-2.5 text-sm font-medium disabled:opacity-40"><Bot size={15} className="inline mr-2"/>Gerar rascunho com IA</button></section></aside>
    <main className="space-y-4">{error&&<Notice type="error">{error}</Notice>}{notice&&<Notice type="ok">{notice}</Notice>}<section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">2. Briefing</div><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Objetivo</label><textarea value={objective} onChange={e=>setObjective(e.target.value)} rows={3} className="mt-1 w-full rounded-xl border border-[#D8D1C9] px-3 py-2"/><div className="grid grid-cols-1 md:grid-cols-2 gap-3 mt-3"><div><label className="text-[11px] uppercase text-[#2B1B0A]/45">Intenção de busca</label><input value={intent} onChange={e=>setIntent(e.target.value)} className="mt-1 w-full rounded-xl border border-[#D8D1C9] px-3 py-2"/></div><div><label className="text-[11px] uppercase text-[#2B1B0A]/45">Contribuição editorial</label><input value={contribution} onChange={e=>setContribution(e.target.value)} className="mt-1 w-full rounded-xl border border-[#D8D1C9] px-3 py-2"/></div></div><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Links internos permitidos</label>{links.map((link,i)=><div className="flex gap-2 mt-1" key={i}><input value={link} onChange={e=>setLinks(links.map((v,j)=>j===i?e.target.value:v))} className="flex-1 rounded-xl border border-[#D8D1C9] px-3 py-2" placeholder="/ ou /blog/slug/"/><button onClick={()=>setLinks(links.filter((_,j)=>j!==i))} className="p-2 text-[#8B2312]"><Trash2 size={15}/></button></div>)}<button onClick={()=>setLinks([...links,''])} className="mt-2 text-sm border border-[#D8D1C9] rounded-xl px-3 py-2"><Plus size={14} className="inline mr-1"/>Link permitido</button></section>
    <section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">3. Referências verificadas</div><p className="text-[12px] text-[#2B1B0A]/50 mt-1">Informe o que cada fonte sustenta e a data em que você conferiu a URL. A IA só pode usar estas referências.</p>{refs.map((ref,i)=><div key={i} className="mt-3 rounded-xl bg-[#FAF8F4] border border-[#E4DFD9] p-3 grid grid-cols-1 md:grid-cols-2 gap-2"><input value={ref.title} onChange={e=>setRefs(refs.map((r,j)=>j===i?{...r,title:e.target.value}:r))} placeholder="Título" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input value={ref.url} onChange={e=>setRefs(refs.map((r,j)=>j===i?{...r,url:e.target.value}:r))} placeholder="https://…" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input value={ref.supports} onChange={e=>setRefs(refs.map((r,j)=>j===i?{...r,supports:e.target.value}:r))} placeholder="O que esta referência sustenta" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><div className="flex gap-2"><input type="date" value={ref.verifiedAt} onChange={e=>setRefs(refs.map((r,j)=>j===i?{...r,verifiedAt:e.target.value}:r))} className="flex-1 border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><button onClick={()=>setRefs(refs.filter((_,j)=>j!==i))} className="p-2 text-[#8B2312]"><Trash2 size={15}/></button></div></div>)}<button onClick={()=>setRefs([...refs,{title:'',url:'',supports:'',verifiedAt:''}])} className="mt-2 text-sm border border-[#D8D1C9] rounded-xl px-3 py-2"><Plus size={14} className="inline mr-1"/>Referência</button></section>
    {payload?.workingTitle&&<section className="space-y-4"><div className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="flex flex-wrap gap-3 justify-between"><div><div className="font-serif text-2xl">{payload.workingTitle}</div><div className="text-[12px] text-[#2B1B0A]/45 mt-1">Estado: {status||'draft'} · provedor: {payload.generator?.provider||'Indisponível'} · modelo: {payload.generator?.model||'Indisponível'} · uso/custo: {payload.generator?.billableUsage||'não confirmado'}</div></div>{status==='failed'&&<button onClick={()=>void generate(true)} className="border border-[#D8D1C9] rounded-xl px-3 py-2 text-sm">Nova tentativa após falha confirmada</button>}{(status==='uncertain'||status==='generating')&&<button onClick={()=>void reconcile()} className="border border-[#D8D1C9] rounded-xl px-3 py-2 text-sm">Verificar operação existente</button>}</div></div><PreviewArticle article={{title:payload.workingTitle,description:payload.description,body:payload.body,references:payload.references}} presentation={presentation}/>{status==='draft'&&<div className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">4. Apresentação e promoção</div><p className="text-[12px] text-[#2B1B0A]/50 mt-1">Escolha humana obrigatória. Nenhuma imagem é gerada ou baixada automaticamente.</p><select value={presentation.kind==='image'?presentation.image.file:'none'} onChange={e=>choosePresentation(e.target.value)} className="mt-3 rounded-xl border border-[#D8D1C9] px-3 py-2 text-sm"><option value="none">Sem imagem adequada</option>{assets.map(a=><option key={a.file} value={a.file}>{a.label}</option>)}</select>{presentation.kind==='image'&&<div className="grid grid-cols-1 md:grid-cols-2 gap-2 mt-2"><input value={presentation.image.alt} onChange={e=>setPresentation({...presentation,image:{...presentation.image,alt:e.target.value}})} className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm" placeholder="Texto alternativo"/><input value={presentation.image.caption} onChange={e=>setPresentation({...presentation,image:{...presentation.image,caption:e.target.value}})} className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm" placeholder="Legenda"/></div>}<button disabled={busy} onClick={()=>void promote()} className="mt-3 bg-[#222D19] text-white rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-40"><FileEdit size={15} className="inline mr-2"/>Criar versão editável privada</button></div>}</section>}
    </main></div>;
}

function ReviewPanel({articleId,onClose,onDone}:{articleId:string;onClose:()=>void;onDone:()=>void}){
  useModalAccessibility(onClose);
  const [data,setData]=useState<any>(null);const [notes,setNotes]=useState('');const [clinicalName,setClinicalName]=useState('');const [evidence,setEvidence]=useState('');const [error,setError]=useState('');const [notice,setNotice]=useState('');const [busy,setBusy]=useState(false);const load=async()=>{try{setData(await blogAdminGet({view:'article',id:articleId}));}catch(e){setError(e instanceof Error?e.message:'Falha ao abrir revisão');}};useEffect(()=>{void load();},[articleId]);if(!data)return <div role="dialog" aria-modal="true" aria-label="Artigo privado" tabIndex={-1} className="fixed inset-0 z-50 bg-black/35 p-4"><div className="max-w-4xl mx-auto bg-[#F6F0E9] rounded-2xl p-5">{error||'Carregando…'}<button className="ml-3" onClick={onClose}>Fechar</button></div></div>;
  const detail=data.detail;const version=detail.versions[0];const payload=version.content_payload_json||{title:version.title,description:version.description,body:version.body_json,references:version.references_json};const presentation=version.presentation_payload_json;const act=async(reviewType:'editorial'|'clinical',decision:'approved'|'changes_requested')=>{setBusy(true);setError('');setNotice('');try{const base={action:'review',versionId:version.id,contentSha256:version.content_sha256,presentationSha256:version.presentation_sha256,reviewType,decision,reviewerName:reviewType==='clinical'?clinicalName:'',notes,evidence:reviewType==='clinical'&&evidence?{clinical_evidence:evidence}:{}};const op=persistentOperation(`review:${version.id}:${reviewType}:${decision}`,base);await blogAdminPost({...base,operationKey:op});setNotice(decision==='approved'?`${reviewType==='clinical'?'Aprovação clínica':'Aprovação editorial'} registrada para esta versão exata.`:'Solicitação de correção registrada; qualquer aprovação anterior desse tipo deixa de ser a decisão atual.');await load();onDone();}catch(e){setError(e instanceof Error?e.message:'Revisão não registrada');}finally{setBusy(false);}};
  return <div role="dialog" aria-modal="true" aria-label="Artigo privado" tabIndex={-1} className="fixed inset-0 z-50 bg-black/35 p-3 md:p-6 overflow-y-auto"><div className="max-w-6xl mx-auto bg-[#F6F0E9] rounded-2xl border border-[#D8D1C9] overflow-hidden"><div className="p-4 border-b border-[#D8D1C9] flex"><div><div className="font-serif text-xl">Revisão · v{version.version_number}</div><details className="text-[11px] text-[#2B1B0A]/45"><summary>Detalhes da versão</summary><div>Conteúdo: {version.content_sha256||'Indisponível'}</div><div>Apresentação: {version.presentation_sha256||'Indisponível'}</div></details></div><button aria-label="Fechar artigo" onClick={onClose} className="ml-auto"><X size={17}/></button></div><div className="p-4 md:p-6 grid grid-cols-1 xl:grid-cols-[1fr_330px] gap-4"> <PreviewArticle article={payload} presentation={presentation}/><aside className="space-y-4">{error&&<Notice type="error">{error}</Notice>}{notice&&<Notice type="ok">{notice}</Notice>}<section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">Decisão editorial</div><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Comentário / correção</label><textarea value={notes} onChange={e=>setNotes(e.target.value)} rows={4} className="mt-1 w-full border border-[#D8D1C9] rounded-lg p-2 text-sm"/><div className="flex gap-2 mt-3"><button disabled={busy||notes.trim().length<3} onClick={()=>void act('editorial','changes_requested')} className="flex-1 border border-[#8B2312]/30 text-[#8B2312] rounded-xl px-2 py-2 text-sm disabled:opacity-40">Pedir correção</button><button disabled={busy} onClick={()=>void act('editorial','approved')} className="flex-1 bg-[#222D19] text-white rounded-xl px-2 py-2 text-sm">Aprovar editorial</button></div></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">Aprovação clínica</div><p className="text-[11px] text-[#2B1B0A]/45 mt-1">O operador do painel é registrado pelo servidor. O nome abaixo identifica quem fez a revisão clínica; clicar aqui não presume que foi a Dra. Karyne.</p><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Responsável clínico</label><input value={clinicalName} onChange={e=>setClinicalName(e.target.value)} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Evidência / referência interna</label><input value={evidence} onChange={e=>setEvidence(e.target.value)} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><button disabled={busy||clinicalName.trim().length<3} onClick={()=>void act('clinical','approved')} className="mt-3 w-full bg-[#565E48] text-white rounded-xl px-2 py-2.5 text-sm font-medium disabled:opacity-40"><CheckCircle2 size={15} className="inline mr-2"/>Registrar aprovação clínica</button></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium text-sm">Histórico desta versão</div>{detail.reviews.filter((r:any)=>r.article_version_id===version.id).map((r:any)=><div key={r.id} className="mt-2 text-[12px] border-t border-[#E4DFD9] pt-2"><div>{r.review_type} · {r.status} · {formatDate(r.reviewed_at)}</div><details><summary>Identidade e versão registradas</summary><div>Versão: {version.version_number}</div><div>Responsável informado: {r.reviewer_name||'não informado'}</div><div>Operador que registrou: {r.recorded_by_user_id||'Indisponível'}</div></details><div className="text-[#2B1B0A]/50">{r.notes}</div></div>)}</section></aside></div></div></div>;
}

function ReviewSection(){const [data,setData]=useState<any>(null);const [selected,setSelected]=useState<string|null>(null);const [error,setError]=useState('');const load=async()=>{try{setData(await blogAdminGet({view:'review-queue',page:1,pageSize:50}));}catch(e){setError(e instanceof Error?e.message:'Fila indisponível');}};useEffect(()=>{void load();},[]);return <div className="space-y-4"><div><h2 className="font-serif text-2xl">Fila de revisão</h2><p className="text-sm text-[#2B1B0A]/55 mt-1">Aprovações valem somente para a versão exata em revisão. Uma nova edição volta para revisão.</p></div>{error&&<Notice type="error">{error}</Notice>}<div className="grid grid-cols-1 lg:grid-cols-2 gap-3">{(data?.items||[]).map((item:any)=><button key={item.id} onClick={()=>setSelected(item.id)} className="text-left bg-white border border-[#E4DFD9] rounded-2xl p-4 hover:border-[#565E48]/40"><div className="flex gap-3"><div className="flex-1"><div className="font-medium">{item.working_title}</div><div className="text-[12px] text-[#2B1B0A]/45 mt-1">v{item.work_version??'—'} · editorial {item.approvals?.editorial?'aprovada':'pendente'} · clínica {item.approvals?.clinical?'aprovada':'pendente'}</div></div><StatusPill status={item.status}/></div></button>)}</div>{!(data?.items||[]).length&&<Notice type="ok">Nenhum artigo pendente na fila atual.</Notice>}{selected&&<ReviewPanel articleId={selected} onClose={()=>setSelected(null)} onDone={()=>void load()}/>}</div>}

export const BlogHub:React.FC=()=>{
  const initial=(()=>{const value=new URLSearchParams(window.location.search).get('blogSection') as BlogSection|null;return SECTIONS.some(s=>s.id===value)?value!:'overview';})();
  const [section,setSection]=useState<BlogSection>(initial);const go=(next:BlogSection)=>{setSection(next);updateBlogSection(next);};
  return <div className="space-y-5"><div className="bg-white border border-[#E4DFD9] rounded-2xl p-1.5 flex gap-1 overflow-x-auto">{SECTIONS.map(item=>{const Icon=item.icon;return <button key={item.id} onClick={()=>go(item.id)} className={`flex-none inline-flex items-center gap-2 px-3.5 py-2 rounded-xl text-sm font-medium ${section===item.id?'bg-[#222D19] text-white':'text-[#2B1B0A]/60 hover:bg-[#F6F0E9]'}`}><Icon size={15}/>{item.label}</button>;})}</div>{section==='overview'&&<OverviewSection go={go}/>} {section==='articles'&&<ArticlesSection/>} {section==='generate'&&<GenerateSection/>} {section==='review'&&<ReviewSection/>} {section==='automations'&&<BlogGscStatus/>}</div>;
};
